<template><div class="page-head"><div><h2>用户列表</h2><div class="muted">查看宠物商城微信用户</div></div></div><ElCard class="card"><div class="filters"><ElInput v-model="q.keyword" clearable placeholder="昵称或 OpenID" style="width:280px" @keyup.enter="load"/><ElSelect v-model="q.status" clearable placeholder="全部状态" style="width:150px"><ElOption label="正常" value="ACTIVE"/><ElOption label="停用" value="DISABLED"/></ElSelect><ElButton type="warning" @click="load">查询</ElButton></div><ElTable :data="rows" v-loading="loading"><ElTableColumn label="用户" min-width="180"><template #default="s"><div class="user"><ElAvatar :src="s.row.avatarUrl"/><span>{{s.row.nickname||'微信用户'}}</span></div></template></ElTableColumn><ElTableColumn prop="openid" label="OpenID" min-width="240" show-overflow-tooltip/><ElTableColumn prop="status" label="状态" width="100"/><ElTableColumn prop="lastLoginAt" label="最近登录" width="180"/><ElTableColumn prop="createdAt" label="注册时间" width="180"/></ElTable><ElPagination class="pager" background layout="total, prev, pager, next" :total="total" :page-size="20" v-model:current-page="q.page" @change="load"/></ElCard></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{api}from'../api';const q=reactive({keyword:'',status:'',page:1,pageSize:20}),rows=ref<any[]>([]),total=ref(0),loading=ref(false);async function load(){loading.value=true;try{const d:any=await api.users(q);rows.value=d.records;total.value=d.total}finally{loading.value=false}}onMounted(load)</script><style scoped>.user{display:flex;align-items:center;gap:10px}.pager{justify-content:flex-end;margin-top:20px}</style>
